# Sync models from all config-managed providers (auto_sync)
Provider = env['ai.provider']
Provider._reconcile_from_config()
for provider in Provider.search([('auto_sync', '=', True), ('status', '=', 'confirmed')]):
    try:
        provider.action_fetch_models()
    except Exception:
        pass
Provider._apply_default_model_from_config()
